.nav-pills [class*=" icon-"].icon-large {
    line-height: .9em;
}
li [class^="icon-"],
.nav li [class^="icon-"],
li [class*=" icon-"],
.nav li [class*=" icon-"] {
    display: inline-block;
    width: 1.25em;
    text-align: center;
}
li [class^="icon-"].icon-large,
.nav li [class^="icon-"].icon-large,
li [class*=" icon-"].icon-large,
.nav li [class*=" icon-"].icon-large {
    /* increased font size for icon-large */

    width: 1.5625em;
}
ul.icons {
    list-style-type: none;
    text-indent: -0.75em;
}
ul.icons li [class^="icon-"],
ul.icons li [class*=" icon-"] {
    width: .75em;
}
.icon-muted {
    color: #eeeeee;
}
.icon-border {
    border: solid 1px #eeeeee;
    padding: .2em .25em .15em;
    -webkit-border-radius: 3px;
    -moz-border-radius: 3px;
    border-radius: 3px;
}
.icon-2x {
    font-size: 2em;
}
.icon-2x.icon-border {
    border-width: 2px;
    -webkit-border-radius: 4px;
    -moz-border-radius: 4px;
    border-radius: 4px;
}
.icon-3x {
    font-size: 3em;
}
.icon-3x.icon-border {
    border-width: 3px;
    -webkit-border-radius: 5px;
    -moz-border-radius: 5px;
    border-radius: 5px;
}
.icon-4x {
    font-size: 4em;
}
.icon-4x.icon-border {
    border-width: 4px;
    -webkit-border-radius: 6px;
    -moz-border-radius: 6px;
    border-radius: 6px;
}
.pull-right {
    float: right;
}
.pull-left {
    float: left;
}
[class^="icon-"].pull-left,
[class*=" icon-"].pull-left {
    margin-right: .3em;
}
[class^="icon-"].pull-right,
[class*=" icon-"].pull-right {
    margin-left: .3em;
}
.btn [class^="icon-"].pull-left.icon-2x,
