.btn-info {
    background-color: #0098D8
}
/****************************************
        Menu top
***************************************/
.top-menu divider-vertical {
    height: 57px;
}
.top-menu .navbar-search {
    margin-top: 14px;
}
.top-menu .label {
    margin-top: 14px;
}
.top-menu .nav > li > a {
    padding: 18px 10px;
}
.dropdown a.btn {
    color: #ffffff;
}
.dropdown .modal-footer {
    padding: 7px 15px;
}
.dropdown-menu .modal-body a {
    padding: 3px 0px;
    float: left;
    clear: none;
}
.dropdown-menu a.link-modal {
    padding: 3px 23px 3px 0;
    float: left;
    color: #4572a7;
}
.dropdown-menu a.link-modal:hover {
    color: #4572a7;
    text-decoration: none;
}
.navbar .bar-root {
    margin-top: 10px;
}
.navbar .bar-root .dropdown-menu a {
    color: #999;
}
.navbar .bar-root .dropdown-menu a:hover {
    background: #222;
}
.navbar .bar-root .dropdown-menu img {
    border: 1px solid #888;
    margin-right: 4px;
}
.navbar .bar-root .label {
    position: relative;
    top: -9px;
}

/*#####################################################################*/

body, html {
    height: 100%;
}

.wrapper {
    min-height: 100%;
    height: auto !important;
    margin: 0 auto -121px;
}

.push {
    height: 147px;
}

/*#####################################################################*/

div.item img {
    width: 940px;
    height: 401px;
}

/*#####################################################################*/
.content {
    padding: 40px 60px 40px 60px;
    min-height: 100%;
}
/*#####################################################################*/

.row.divider:last-child {
    margin-bottom: 40px;

    border: none;
}

.row-divider {
    border: none;
    margin: 10px 0 21px;
    border-bottom: 1px dotted #0098D8;
}

.content-divider {
    margin-bottom : 10px;
    margin-top : 10px;

    border: none;
    border-bottom: 1px solid #0098D8;

    -webkit-box-shadow: inset 0 16px 8px -20px rgba(0, 0, 0, 0.4);
    -moz-box-shadow: inset 0 15px 8px -20px rgba(0, 0, 0, 0.4);
    -webkit-mask-image: -webkit-linear-gradient(left, rgba(0, 0, 0, 0), black 20%, black 80%, rgba(0, 0, 0, 0) 100%);
    -moz-mask-image: -moz-linear-gradient(left, rgba(0, 0, 0, 0), black 20%, black 80%, rgba(0, 0, 0, 0) 100%);

}

/*#####################################################################*/

#nav {
    margin-bottom: .5em;
}

#nav > #pages-nav {
    padding: 0;
    margin: 0;

    border-top: 1px solid #A1A1A1;
}

#nav > #pages-nav > li {
    position: relative;
    top: -1px;

    float: left;

    padding: 0 40px 0 0;
    margin: 0;

    list-style: none;

    border-top: 1px solid #A1A1A1;
}

#nav > #pages-nav > li:last-child {
    padding-right: 0;
}

#nav > #pages-nav > li > a {
    position: relative;
    top: -1px;
    display: block;
    padding: 15px 5px 5px;
    color: #888;
    text-transform: uppercase;
    border-top: 1px solid transparent;
    cursor: pointer;
}

#nav > #pages-nav > li > a:hover,
#nav > #pages-nav > li.dropdown.open > a {
    color: #0098D8;

    text-decoration: none;

    border-top-color: #0098D8;
    border-top-width: 1px;
}

#nav > #pages-nav > li.active a {
    padding-top: 12px;
    top: -2px;

    color: #0098D8;

    border-top-color: #0098D8;
    border-top-width: 4px;
}

#nav > #pages-nav > li > a > .caret {
    position: relative;
    top: -2px;

    margin-left: .5em;
}

#nav .dropdown-menu a:hover {
    background-color: #0098D8;
}

#nav .dropdown-menu > li > a {
    padding: 6px 12px;
}

#nav .dropdown-menu i {
    margin-right: .5em;

    font-size: 14px;
}

#nav .dropdown-menu::before {
    content: '';
    display: inline-block;
    border-left: 7px solid transparent;
    border-right: 7px solid transparent;
    border-bottom: 7px solid #CCC;
    border-bottom-color: rgba(0, 0, 0, 0.2);
    position: absolute;
    top: -7px;
    left: 9px;
}

#nav .dropdown-menu::after {
    content: '';
    display: inline-block;
    border-left: 6px solid transparent;
    border-right: 6px solid transparent;
    border-bottom: 6px solid white;
    position: absolute;
    top: -6px;
    left: 10px;
}

/*#####################################################################*/

#welcome {
    padding-left: 90px;
    text-align: center;
}

/*#####################################################################*/

i.icon, .slash, i.icon-middle {
    margin-right: 5px;
    color: #0098D8;
    font-size: 18px;
    line-height: 18px;
}

i.icon-middle {
    font-size: 20px;
    margin-right: 10px;
    line-height: 30px;
}

/****************************************
        Footer
***************************************/

.footer {
    margin-top: 0;
    line-height: 12px;
    border-top: 1px solid #292929;
}

.footer-inner {
    padding: 15px 0;

    font-size: 12px;
    background: #111;
    color: #999;
}

.footer a {
    color: #999;
}

.footer a:hover {
    color: #FFF;
    text-decoration: none;
}

.extra {
    border-top: 1px solid #E5E5E5;
    background-color: whiteSmoke;
}

.extra-inner {
    padding: 20px 0;
    font-size: 11px;
}

.extra span {
    color: #666;
    cursor: pointer;
}

.extra h4 {
    margin-bottom: 1em;

    font-weight: 400;
}

.extra ul {
    padding: 0;
    margin: 0;
}

.extra li {
    margin-bottom: .6em;
    list-style: none;
}

/***********************************************************/

.hero-home {
    background: url('../img/online_banking_hero.jpg') no-repeat;
    color: #0082D8;
    position: relative;
}

.hero-home p {
    color: #0082D8;
}

.large-btn:hover,
.large-btn:active,
.large-btn.active {
    background-color: #5BB900;
}

.large-btn {
    font-size: 24px;
    padding: 12px 32px;
    font-weight: bold;
    margin-top: 15px;

    background: #65C31F;
    color: white;
    border-color: #57AF17;
    font-weight: bold;
}

.text-shadow {
    text-shadow: 1px 2px 5px black;
}

.btn.text-shadow {
    text-shadow: 2px 1px 1px black;
}

.feature-description {
    border-radius: 15px;
    padding: 15px;
    position: relative;

    background: #383838;
}


.margin15 {
    margin-bottom: 15px
}

.margin7top {
    margin-top: 7px
}

.margin20top {
    margin-top: 20px
}

a.actions {
    padding: 4px 9px!important;

    border: 2px solid #A1A1A1;
    border-radius: 4px;
    font-size: 11px;
    line-height: 1;
    margin-left: 20px;
    text-transform: uppercase;
    margin-top: 10px
}

.accordion-heading {
    background-color: whiteSmoke;
}

.footer.fixed {
    position: fixed;
    bottom: 0;
    right: 0;
    left: 0;
}

.carousel-caption.custom {
    top: 0;
    width: 200px;

    background-color:  rgba(0, 0, 0, 0.8)
}

.item > img {
    margin-left: 230px;
}

.carousel-control.custom.left,.carousel-control.custom.right {
    font-family: 'Helvetica Neue', Helvetica,Arial, sans-serif;
    background: white;
    border: none;
    color: #2F96B4;
    top: 50%;
}

.carousel-control.custom.left {
    left: -50px;
}

.carousel-control.custom.right {
    right: -50px;
}

.button-large {
    font-size: 20px;
    padding: 20px 50px 20px 50px;
}

.carousel-btn,.hero-btn {
    position: absolute;
    border-radius: 15px
}

.carousel-btn {
    bottom: 80px;
    left: 27px;
}

.hero-btn {
    right: 130px;
    top:35%;
}

.signin-controls input {
    padding: 8px 15px 8px 50px;
    background-color: #FDFDFD;
    width: 255px;
    display: block;
    margin: 0;
    box-shadow: inset 0 0 2px rgba(47, 150, 252, 0.8)
}

input.login {
    background: url(../img/user_login.png) no-repeat;
}

input.password {
