body, html {
    height: 100%;
}

.wrapper {
    min-height: 100%;
    height: auto !important;
    margin: 0 auto -121px;
}

.push {
    height: 147px;
}

/*#####################################################################*/

div.item img {
    width: 940px;
    height: 401px;
}

/*#####################################################################*/
.content {
    padding: 40px 60px 40px 60px;
    min-height: 100%;
}
/*#####################################################################*/

.row.divider:last-child {
    margin-bottom: 40px;

    border: none;
}

.row-divider {
    border: none;
    margin: 10px 0 21px;
    border-bottom: 1px dotted #0098D8;
}

.content-divider {
    margin-bottom : 10px;
    margin-top : 10px;

    border: none;
    border-bottom: 1px solid #0098D8;

    -webkit-box-shadow: inset 0 16px 8px -20px rgba(0, 0, 0, 0.4);
    -moz-box-shadow: inset 0 15px 8px -20px rgba(0, 0, 0, 0.4);
    -webkit-mask-image: -webkit-linear-gradient(left, rgba(0, 0, 0, 0), black 20%, black 80%, rgba(0, 0, 0, 0) 100%);
    -moz-mask-image: -moz-linear-gradient(left, rgba(0, 0, 0, 0), black 20%, black 80%, rgba(0, 0, 0, 0) 100%);

}

/*#####################################################################*/

#nav {
    margin-bottom: .5em;
}

#nav > #pages-nav {
    padding: 0;
    margin: 0;

    border-top: 1px solid #A1A1A1;
}

#nav > #pages-nav > li {
    position: relative;
    top: -1px;

    float: left;

    padding: 0 40px 0 0;
    margin: 0;

    list-style: none;

    border-top: 1px solid #A1A1A1;
}

#nav > #pages-nav > li:last-child {
    padding-right: 0;
}

#nav > #pages-nav > li > a {
    position: relative;
    top: -1px;
    display: block;
    padding: 15px 5px 5px;
    color: #888;
    text-transform: uppercase;
    border-top: 1px solid transparent;
    cursor: pointer;
}

#nav > #pages-nav > li > a:hover,
#nav > #pages-nav > li.dropdown.open > a {
    color: #0098D8;

    text-decoration: none;

    border-top-color: #0098D8;
    border-top-width: 1px;
}

#nav > #pages-nav > li.active a {
    padding-top: 12px;
    top: -2px;

    color: #0098D8;

    border-top-color: #0098D8;
    border-top-width: 4px;
}

#nav > #pages-nav > li > a > .caret {
    position: relative;
    top: -2px;

    margin-left: .5em;
}

#nav .dropdown-menu a:hover {
    background-color: #0098D8;
}

#nav .dropdown-menu > li > a {
    padding: 6px 12px;
}

#nav .dropdown-menu i {
    margin-right: .5em;

    font-size: 14px;
}

#nav .dropdown-menu::before {
    content: '';
    display: inline-block;
    border-left: 7px solid transparent;
    border-right: 7px solid transparent;
    border-bottom: 7px solid #CCC;
    border-bottom-color: rgba(0, 0, 0, 0.2);
    position: absolute;
    top: -7px;
    left: 9px;
}

#nav .dropdown-menu::after {
    content: '';
    display: inline-block;
    border-left: 6px solid transparent;
    border-right: 6px solid transparent;
    border-bottom: 6px solid white;
    position: absolute;
    top: -6px;
    left: 10px;
}

