    vertical-align: bottom;
}

.board .table td {
    border-bottom: 1px solid #DEDEDE;
    border-top: 1px solid white;
    padding: 5px 20px;
    text-shadow: 0px 1px 1px white;
}

.board-content .control-group {
    margin: 0px;
    padding-top: 10px;
    padding-bottom: 10px;
}

.board-content hr {
    margin: 0;
}

article form {
    margin-bottom: 0
}

#nav > #pages-nav > li.active div {
    padding-top: 12px;
    top: -2px;
    color: #0098D8;
    border-top-color: #0098D8;
    border-top-width: 4px;
    text-decoration: none;
}

#nav > #pages-nav > li > div {
    position: relative;
    top: -1px;
    display: block;
    padding: 15px 5px 5px;
    color: #888;
    text-transform: uppercase;
    border-top: 1px solid transparent;
    cursor: pointer;
    text-decoration: none;
}


.number {
    margin-top: 6px;
    width: 40px;
    height: 40px;
    font-size: 28px;
    font-weight: 600;
    text-align: center;
    line-height: 40px;
    color: white;
    background: #08C;
    border: 3px solid white;
    box-shadow: 1px 1px 3px rgba(0, 0, 0, .4);
    border-radius: 40px;
    text-shadow: 1px 1px 2px rgba(0, 0, 0, .4);
}

ol.questions > li {
    padding-bottom: 12px;
    font-size: 15px
}

div.disclaimer {
    border: 1px dashed #0098D8;
    margin-top: 10px;
    padding: 10px;
}

@media (max-width:979px) {
    button.signin {
        margin-left: 15px;
        border-radius: 20px!important;
    }
}

@media (max-width: 260px) {
    .nav.float-right {
        float: left!important;
    }
}

@media (min-width: 261px) {
    .nav.float-right {
        float: right!important;
    }
}

